const demoras = [5, 30, 26, 12, 48, 24, 72]; // horas que demoró cada envío

// 1) Estilo imperativo: un acumulador que cambia dentro de un bucle
let total1 = 0;
for (const h of demoras) {
  if (h > 24) total1 += h;
}

// 2) Estilo funcional: se encadenan funciones, nada cambia de valor
const total2 = demoras.filter(h => h > 24).reduce((acum, h) => acum + h, 0);

// 3) Estilo recursivo: la suma de una lista es el primero más la suma del resto
function sumaMayores(lista) {
  if (lista.length === 0) return 0;
  const [primero, ...resto] = lista;
  return (primero > 24 ? primero : 0) + sumaMayores(resto);
}
const total3 = sumaMayores(demoras);

console.log(total1, total2, total3);

#include <stdio.h>

int main(void) {
    int demoras[] = {5, 30, 26, 12, 48, 24, 72};
    int n = sizeof demoras / sizeof demoras[0];
    int total = 0;
    for (int i = 0; i < n; i++) {
        if (demoras[i] > 24) total += demoras[i];
    }
    printf("%d\n", total);
    return 0;
}

