// Suma de pasos de la conjetura de Collatz para n < 100000
// (en el artículo se midió con n < 1.000.000, que en el navegador tardaría demasiado)
let total = 0;
for (let n = 1; n < 100000; n++) {
  let x = n;
  while (x !== 1) {
    x = x % 2 === 0 ? x / 2 : 3 * x + 1;
    total++;
  }
}
console.log(total);
